TESTDATA["pet3-t1"] = {"title": "Cambridge PET 3 · Test 1", "format": "2010", "reading": [{"part": 1, "items": [{"n": 1, "text": "", "img": "data:image/jpeg;base64,", "q": "", "options": ["Elena and Tim have discovered another good restaurant.", "Elena and Tim think the restaurant’s prices are reasonable.", "Elena and Tim will have to try the restaurant on their next visit."], "answer": "B"}, {"n": 2, "text": "", "img": "data:image/jpeg;base64,", "q": "", "options": ["All City Bus journeys cost exactly the same.", "You need to have the correct money when you board the bus.", "You must keep your ticket ready for checking."], "answer": "B"}, {"n": 3, "text": "", "img": "data:image/jpeg;base64,", "q": "Why did the record shop phone?", "options": ["to apologise for a mistake with Frank’s order", "to suggest Frank comes in later this week", "to say that Frank’s CD is ready for collection"], "answer": "A"}, {"n": 4, "text": "", "img": "data:image/jpeg;base64,", "q": "", "options": ["You can buy a meal for only £3 at lunchtime.", "A charge of £3 is added to each bill at lunchtime.", "Each customer will have to pay at least £3 at lunchtime."], "answer": "C"}, {"n": 5, "text": "", "img": "data:image/jpeg;base64,", "q": "", "options": ["Students should check when this Thursday’s lecture begins.", "Dr Hatton had forgotten to announce the change on Thursday.", "The location of Thursday’s lecture will be different from usual."], "answer": "C"}]}, {"part": 2, "people": [{"n": 6, "name": "Peter", "text": "Peter is studying English. He hopes either to write plays or to be an actor. He particularly enjoys plays about real people who led interesting lives.", "answer": "G"}, {"n": 7, "name": "Glenda", "text": "Glenda is studying the history of music at college. She wants to listen to as much music from the past as possible, and particularly likes listening to people singing.", "answer": "C"}, {"n": 8, "name": "Wong", "text": "Wong is a dancer from China. He would like to see people performing dances from as many other parts of the world as possible to give him some new ideas.", "answer": "A"}, {"n": 9, "name": "Maria", "text": "Maria is celebrating her birthday tomorrow. She wants to go out for the whole day with her friends. They all enjoy listening to pop music.", "answer": "B"}, {"n": 10, "name": "Ruth", "text": "Ruth is a teacher who is planning to start a drama club for the children at her school. She would like to see some children acting if possible.", "answer": "F"}], "texts": [{"letter": "A", "title": "International Youth Celebrations", "text": "Local youth groups, together with students from various countries including Spain, Finland, Austria and Estonia, are each performing three dance pieces. Then they will join together in a play about international friendship. The evening will finish with the singing of songs from different countries."}, {"letter": "B", "title": "River Festival", "text": "A day of fun on the river bank, with a Chinese theme. Street entertainers and pop musicians perform during the day, followed by fireworks in the evening. Something for everybody to watch, both children and adults."}, {"letter": "C", "title": "Songs of Summer", "text": "The Hunton Consort consists of eight voices singing music from hundreds of years ago right up to modern times. The group will perform songs, old and new, all of which are about the summer."}, {"letter": "D", "title": "Music in the Open Air", "text": "Well-known nationally for their traditional dance music, Jimmy Locke and his band play throughout the day in the open air on the Promenade Bandstand – if the weather allows!"}, {"letter": "E", "title": "Life Flows Between Us", "text": "Kent Arts and Libraries present the first performance of a new dance group called the Street Dancing Company. The group will perform dances from the past on several of the bridges in the town."}, {"letter": "F", "title": "A Star May Be Born", "text": "Toni Arthur produces plays with seven- to eleven-year-olds, performed at the weekends for parents, family and friends. The plays come from children’s stories, and encouragement from the audience is always very welcome."}, {"letter": "G", "title": "Vita and Harold", "text": "The Image Theatre Company dramatises the love-letters of Vita Sackville-West and Harold Nicholson. The play is about the couple’s lives and their most unusual marriage. Unsuitable for children."}, {"letter": "H", "title": "Variety Music Evening", "text": "A great evening with the latest pop songs, and comedy and dancing from several great and unusual performers. Members of the audience will be invited to join in and will have the chance of winning tickets to a theatre show."}]}, {"part": 3, "title": "The Outdoor Centre", "text": "Opening times\nWater sports: 10 am–6 pm\nPlay Park: 10 am–5.30 pm\n\nEntrance/Car park fees\nLow season: Weekdays £2.00 per car; Weekends £3.00 per car. High season: 23 July–11 September; Weekdays and weekends £3.00 per car.\nFees are for car with four people. Each extra person is 50p. Fees to be paid at main office.\nThe centre is not a private club; it is an organisation whose aim is to provide outdoor sport and recreation facilities for all members of the public.\nGroup visitors are requested to inform the centre in advance of their intended visit.\n\nWindsurfing — One-day course\nBeginner windsurfing courses are offered on Saturdays and Sundays when the weather is good enough. Learning to windsurf is a lot of fun. The excitement when you sail across the water for the first time is not easily forgotten. Boards with small sails are available for beginners.\nCourse fee: £32.50 (this includes all equipment)\n\nOne-day adventure course\nThis is an opportunity you have been waiting for. Come and try sailing, climbing, surfing and archery. This course is intended to introduce outdoor activities to adults in a fun, leisurely manner. You do not need to be extremely fit or to have had previous experience of the activities. All you need is to be interested.\nCourse fee: £22.50\n\nPlay Park\nThe Play Park is suitable for children from two to ten years of age. It is one of the best of its type in the country. It has sand and water play, slides, large ball pool, play castle and much, much more. Next year the centre will open a new Play Palace and Play Ship.\n\nGroup day and residential courses\nWe also offer day and long weekend courses for groups. We receive regular visits from schools, colleges and youth groups. There are three large rooms with twelve beds in each, which can be booked in advance for groups of up to 36 people (minimum 12).\n\nSummer adventure holidays (for 8–14 years of age)\nSailing   Climbing   Windsurfing   Fun Games\nSafety is of primary importance at the Outdoor Centre. All staff are fully trained in First Aid, and qualified to teach the activities on offer. We also make certain that all children only take part in activities that are suitable for their age and physical abilities. For this programme children must be able to swim 25 metres and be in good physical health.", "items": [{"n": 11, "q": "In August, four people visiting the centre together by car would pay more than two people.", "answer": "B"}, {"n": 12, "q": "The centre has activities for a range of age groups.", "answer": "A"}, {"n": 13, "q": "There are windsurfing courses every weekend.", "answer": "B"}, {"n": 14, "q": "The centre has special equipment for people who are learning to windsurf.", "answer": "A"}, {"n": 15, "q": "There is an extra hire charge for the board on the windsurfing course.", "answer": "B"}, {"n": 16, "q": "The adventure course is suitable for beginners.", "answer": "A"}, {"n": 17, "q": "The centre is planning to add extra facilities to the Play Park.", "answer": "A"}, {"n": 18, "q": "It is possible for individual visitors to stay overnight at the centre.", "answer": "B"}, {"n": 19, "q": "On the holiday programme children are allowed to do any sport they are interested in.", "answer": "B"}, {"n": 20, "q": "Summer adventure holidays are open to any child between eight and fourteen years who can swim.", "answer": "B"}]}, {"part": 4, "title": "", "text": "‘The best age to start learning the violin is between three and six,’ says Margaret Porter, a violinist and music teacher. ‘It’s the time when you are learning about the world.’ Margaret, who lives in London, prefers to take pupils at three and four, although she has made lots of exceptions for keen five-year-olds. When she started teaching the violin in 1972, her first class consisted of her children’s five-year-old school friends.\n\nMargaret’s pupils have group lessons. Each group has about a dozen pupils and each lesson lasts an hour, once a fortnight. In addition, each pupil has one individual lesson a week with her. Parents also have to attend the classes. It is important that the parents take an active interest in the lessons.\n\nFrom the earliest lessons pupils learn to play by ear. They do not even try to read music until they have been playing for several years, and for a long time there is a big difference between their playing and reading of music. Margaret says that her method is not supposed to produce great violinists, and always suggests that pupils who perform particularly well should leave and study the violin using more traditional methods.", "items": [{"n": 21, "q": "What is the writer trying to do in the text?", "options": ["explain why Margaret likes teaching the violin", "describe a different way of learning the violin", "give advice on how to find a music teacher", "explain why Margaret has a lot of pupils"], "answer": "B"}, {"n": 22, "q": "Why should someone read the text?", "options": ["to discover how Margaret learnt the violin", "to learn why it is important to read music", "to find out about Margaret’s teaching method", "to learn why children should play the violin"], "answer": "C"}, {"n": 23, "q": "What opinion does Margaret have about her best pupils?", "options": ["They ought to find another teacher.", "They will become great violinists using her method.", "They could try harder.", "They take several years to learn to read music."], "answer": "A"}, {"n": 24, "q": "Margaret’s first pupils were", "options": ["her children.", "three- and four-year-olds.", "her own friends.", "her children’s friends."], "answer": "D"}, {"n": 25, "q": "Which of the following would Margaret include in an advertisement for her classes?", "options": ["Learn to play the violin with your children – 2 lessons a week.", "Watch your children learn to play the violin.", "Group violin lessons for children – no more than 5 per group.", "We’ll look after your children while you learn the violin."], "answer": "B"}]}, {"part": 5, "title": "NEW OPPORTUNITIES WITH AN OPEN UNIVERSITY DEGREE", "text": "Like any other university, the Open University can (0) ……… (give) you a degree. However, you don’t have to [26] working to study. It can also open up a whole variety [27] interests.\n\nIf you have [28] studied before, you will enjoy the special, new pleasure of [29] your knowledge. You will make friends of [30] kinds. You may also [31] that your qualification provides new career opportunities.\n\nYou don’t actually [32] to the Open University for lectures, but study at home, using television, radio and computer software. You can [33] one class a month if you wish at an Open University centre. Of course, there are exams to take, as in [34] university.\n\nIf you [35] like to know more, all you have to do is complete the form below. It could be the start of a wonderful new period in your life.", "gaps": {"26": {"options": ["stop", "end", "break", "leave"], "answer": "A"}, "27": {"options": ["from", "of", "in", "for"], "answer": "B"}, "28": {"options": ["ever", "never", "often", "always"], "answer": "B"}, "29": {"options": ["growing", "changing", "adding", "increasing"], "answer": "D"}, "30": {"options": ["all", "each", "both", "every"], "answer": "A"}, "31": {"options": ["suggest", "find", "wish", "want"], "answer": "B"}, "32": {"options": ["join", "enter", "arrive", "go"], "answer": "D"}, "33": {"options": ["give", "attend", "learn", "study"], "answer": "B"}, "34": {"options": ["any", "some", "many", "most"], "answer": "A"}, "35": {"options": ["did", "will", "would", "can"], "answer": "C"}}}], "writing": [{"part": 1, "title": "Here are some questions about going to the theatre.", "items": [{"n": 1, "first": "Theatre tickets are more expensive than last year.", "before": "Last year, theatre tickets", "after": "than they are now.", "answers": ["were cheaper", "were less expensive"]}, {"n": 2, "first": "The booking office telephone is often engaged.", "before": "It is often", "after": "phone the booking office.", "answers": ["difficult to", "impossible to", "hard to", "a problem to"]}, {"n": 3, "first": "Peter said, “Why don’t you go to the booking office yourself?”", "before": "Peter said, “How", "after": "to the booking office yourself?”", "answers": ["about going"]}, {"n": 4, "first": "Many theatres accept credit cards.", "before": "At many theatres you", "after": "credit card.", "answers": ["can use a", "can pay by"]}, {"n": 5, "first": "You can’t smoke in the theatre.", "before": "Smoking", "after": "in the theatre.", "answers": ["is not allowed", "is not permitted", "is forbidden"]}]}, {"part": 2, "items": [{"n": 6, "kind": "message", "task": "You are going to spend some time with your Scottish friend Douglas next Saturday.\n\nWrite an email to Douglas. In your email, you should\n• arrange to meet Douglas next Saturday\n• suggest something you could do together\n• say how long you will be able to spend with him.\n\nWrite 35–45 words on your answer sheet.", "points": ["dare appuntamento a Douglas per sabato prossimo", "proporre cosa fare insieme", "dire quanto tempo potrà stare con Douglas"]}]}, {"part": 3, "items": [{"n": 7, "kind": "story", "task": "Your English teacher has asked you to write a story.\nYour story must begin with this sentence:\n\nI wanted to leave the city as soon as possible.\n\nWrite your story in about 100 words on your answer sheet."}, {"n": 8, "kind": "letter", "task": "This is part of a letter you receive from a pen-friend.\n\n“You’re keen on cooking, aren’t you? What meals do you like to cook? Where do you buy all your food from?”\n\nNow write a letter, answering your friend’s questions.\nWrite your letter in about 100 words on your answer sheet."}]}], "listening": [{"part": 1, "audio": "audio/pet3-t1-l1.mp3", "items": [{"n": 1, "q": "What was in the woman’s bag?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "B"}, {"n": 2, "q": "Which film is the man talking about?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "B"}, {"n": 3, "q": "What should the woman do first?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "C"}, {"n": 4, "q": "What is David going to do this weekend?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "B"}, {"n": 5, "q": "How did the man get to work today?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "A"}, {"n": 6, "q": "Which tie does the man choose?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "C"}, {"n": 7, "q": "What time is the appointment?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "C"}]}, {"part": 2, "intro": "You will hear an announcement about what’s on television tomorrow.", "audio": "audio/pet3-t1-l2.mp3", "items": [{"n": 8, "q": "The Railway Princess is on television from", "options": ["9.00 to 10.00.", "9.00 to 10.30.", "9.30 to 11.00."], "answer": "B"}, {"n": 9, "q": "There is a music programme for teenagers", "options": ["early in the morning.", "before lunch.", "at lunchtime."], "answer": "C"}, {"n": 10, "q": "You can see a football match between", "options": ["Ireland and Spain.", "Brazil and Ireland.", "Spain and Italy."], "answer": "B"}, {"n": 11, "q": "If the weather is bad, there will be no", "options": ["cycling.", "skiing.", "tennis."], "answer": "C"}, {"n": 12, "q": "In the quiz programme, teams have to guess", "options": ["the year.", "the person.", "the place."], "answer": "A"}, {"n": 13, "q": "What kind of film is I Could Live Forever?", "options": ["a comedy", "a musical", "a thriller"], "answer": "B"}]}, {"part": 3, "intro": "You will hear a radio announcer talking about Plymouth Sea Life Centre.", "audio": "audio/pet3-t1-l3.mp3", "notes": "Plymouth Sea Life Centre\n\nCOST\nAdults £ [14], children £2.00.\nSpecial prices for over sixties and school groups.\n\nOPENING TIMES\nEvery day except 25 and 26 December.\n\nFOR CHILDREN\nSpecial quiz.\nAnimals are fed every [15] from 9.30 am.\nSlide and [16] shows from 10.00 am.\n\nGROUPS\nGuided tours available – ask at the [17] .\n\nNEW ATTRACTION\nWalk through the big [18] made of glass.\n\nREFRESHMENTS\nFamily area sells [19], cold drinks, ice creams.\n\nFOR MORE INFORMATION TELEPHONE 01743 564219.", "answers": {"14": ["£3.70", "3.70", "3 pounds 70"], "15": ["hour", "hourly"], "16": ["video", "videos"], "17": ["information desk"], "18": ["tunnel"], "19": ["snack", "snacks"]}}, {"part": 4, "intro": "You will hear a conversation between a girl, Jane, and her brother, Michael, about a Spanish family who are coming to visit them in England.", "audio": "audio/pet3-t1-l4.mp3", "items": [{"n": 20, "q": "This will be the Sanchez family’s first trip to England.", "answer": "A"}, {"n": 21, "q": "Michael suggests sightseeing in London.", "answer": "A"}, {"n": 22, "q": "The Sanchez children are teenagers.", "answer": "B"}, {"n": 23, "q": "Jane has been to the car museum.", "answer": "A"}, {"n": 24, "q": "Michael thinks everyone enjoys visiting museums.", "answer": "B"}, {"n": 25, "q": "Jane and Michael have bought tickets for the tennis competition.", "answer": "B"}]}]};
